 function sync(){enterButton.disabled=!current()||!inS4()||entered||locked();exitButton.disabled=!active()||!!services?.blocksInput;actionButton.disabled=!active()||acting||locked()||!!services?.blocksInput;doorButton.disabled=actionButton.disabled;root.dataset.gohyeonNativeActive=String(active());positionHud.refresh()}
